        private static final long P6 = (long) P5;
        private int value;

        public static final Field Z0 = new Field(0);
        public static final Field Z1 = new Field(1);

        public Field(int a) {
            this.value = cv(a);
        }

        public Field(long a) {
            this.value = cv(a);
        }

        public static Field newField(long a) {
            return new Field(a);
        }

        public static Field newUnchecked(int a) {
            Field f = new Field(0);
            f.value = a;
            return f;
        }

        private static int hi(int a) {
            if (a >= P5) a -= P5;
            return a;
        }

        private static int lo(int a) {
            if (a < 0) a += P5;
            return a;
        }

        private static int cv(long a) {
            return lo((int) (a % P6));
        }

        public Field inv() {
            return pow(P5 - 2);
        }

        public Field pow(long b) {
            if (b == 0) return newUnchecked(1);
            Field res = this.pow(b / 2);
            res = res.mul(res);
            if (b % 2 == 1) res = res.mul(this);
            return res;
        }

        public Field add(Field a) {
            return newUnchecked(hi(this.value + a.value));
        }

        public Field sub(Field a) {
            return newUnchecked(lo(this.value - a.value));
        }

        public Field mul(Field a) {
            return newUnchecked(cv((long) this.value * (long) a.value));
        }

        public Field div(Field a) {
            return this.mul(a.inv());
        }

        public Field neg() {
            return newUnchecked(lo(-this.value));
        }

        @Override
        public String toString() {
            return Integer.toString(this.value);
        }
    }

    // Binomial Coefficient (C(n,r))
    public static class Cnr {
