            this.n = n;
            f = new Field[n + 1];
            f[0] = Field.Z1;
            for (int i = 1; i <= n; i++) {
                f[i] = f[i - 1].mul(Field.newField(i));
            }
            fi = new Field[n + 1];
            Arrays.fill(fi, Field.Z1);
            fi[n] = f[n].inv();
            for (int i = n - 1; i >= 0; i--) {
                fi[i] = fi[i + 1].mul(Field.newField(i + 1));
            }
        }

